// src/services/bpmn-format-service.ts
class BpmnFormatService {
  fs;
  constructor(fs = getFileSystem()) {
    this.fs = fs;
  }
  async execute(bpmnPath, outPath) {
    const [error, exitCode] = await catchError(this.formatDiagram(bpmnPath, outPath));
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "format failed",
        Instructions: error.message
      });
      return 1;
    }
    return exitCode ?? 0;
  }
  async formatDiagram(bpmnPath, outPath) {
    const bpmn = await parseBpmnFile(this.fs, bpmnPath);
    if (!bpmn)
      return 1;
    const layout = generateBpmnLayout(bpmn.xml, bpmn.processes);
    if (!layout.success) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: layout.message,
        Instructions: layout.instructions
      });
      return 1;
    }
    const resolvedOut = outPath ? this.fs.path.resolve(outPath) : bpmn.absolutePath;
    if (outPath) {
      await this.fs.mkdir(this.fs.path.dirname(resolvedOut), {
        recursive: true
      });
    }
    await this.fs.writeFile(resolvedOut, layout.content, "utf-8");
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "MaestroBpmnFormat",
      Data: {
        File: resolvedOut,
        ShapeCount: layout.shapeCount,
        EdgeCount: layout.edgeCount
      }
    });
    return 0;
  }
}
export {
  BpmnFormatService
};

